INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('xx-2662-xx','xX_2662_Xx','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"xx-2662-xx","name":"xX_2662_Xx","team":"demon","ability":"You win with good, have a Demon''s ability, & cannot kill yourself. If all Minions publicly guess you are 2662 & you''re not about to die, evil wins. [+1 Outsider]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-2662 is an eldritch being that isn''t interested in taking up the mantle of world-ending destroyer, rather content with playing video games & consuming online media.","summaryBullets":["xX_2662_Xx has the powers of a Demon, knows the evil team, and registers foremost as evil & the Demon, but is secretly colluding for the good team in their crusade & won''t win with the evil team.","Even if the game ends by another character''s ability, xX_2662_Xx''s victory is tied to the good team rather than the evil team.","Normal win conditions are in effect, with good winning on xX_2662_Xx''s death, and evil winning upon there being only 2 people left or the good team being left with no possible way to win.","If all Minions publicly come out as Minions to guess that the Demon is xX_2662_Xx {{i|(also naming who it is)}}, the evil team wins.","xX_2662_Xx does not change who they win with when they die - even if the evil team carries on their legacy, their loyalty still lies with the good team.","If the guess is made whilst the Demon isn''t actually xX_2662_Xx, nothing happens {{i|(except the fact that the entire evil team is now publicly outed)}}.","xX_2662_Xx cannot die to their own ability, but they are still free to attack themselves or corpses to waste any kills."],"howToRun":["While setting up the game, before putting character tokens in the bag, remove xX_2662_Xx''s token and a Townsfolk token, then add a Demon character token and an Outsider character token. Add xX_2662_Xx''s **IS xX_2662_Xx** reminder token to the Grimoire. Put the swapped Demon character token in the bag, not xX_2662_Xx''s character token.","While preparing the first night, put xX_2662_Xx''s **IS xX_2662_Xx** reminder token by the Demon character token, changing that player''s character to xX_2662_Xx. Wake the Demon, show them the “You Are” info token then the xX_2662_Xx character token, put them to sleep. Whilst retaining the ability of another Demon, they win with the good team instead of the evil team.","If xX_2662_Xx would die to themselves, they remain alive.","At any time during the game {{i|(except if xX_2662_Xx is about to die by nomination & execution)}}, if all Minions publicly guess that the Demon is xX_2662_Xx whilst naming them, the game ends. Declare that the evil team wins.","If the game ends and the evil team would have won, declare that xX_2662_Xx isn''t part of that win, and loses, even if xX_2662_Xx is dead.","If the game ends and the good team would have won, declare that xX_2662_Xx is part of that win, even if xX_2662_Xx is dead."],"iconBy":"le_nuberto","jinxes":[{"name":"Lleech","align":"evil","text":"xX_2662_Xx cannot kill their Lleech''ed host.","id":"lleech"},{"name":"Poppy Grower","align":"good","text":"Only 1 jinxed character can be in play.","id":"poppygrower"},{"name":"Scarlet Woman","align":"evil","text":"If the xX_2662_Xx dies, their ability lasts (except the 2nd Demon ability), and the Scarlet Woman instead becomes that 2nd Demon.","id":"scarletwoman"},{"name":"Snake Charmer","align":"good","text":"The Snake Charmer is poisoned and secretly wins with evil instead of good.","id":"snakecharmer"},{"name":"Spy","align":"evil","text":"Instead of adding 1 Outsider, 1 Townsfolk is secretly drunk. When the Spy views the Grimoire, they see xX_2662_Xx as the Demon whose ability they have and doesn''t know who is secretly drunk.","id":"spy"},{"name":"Summoner","align":"evil","text":"The Storyteller (and not the Summoner) can choose if the summoned Demon is secretly xX_2662_Xx or not.","id":"summoner"},{"name":"Widow","align":"evil","text":"Instead of adding 1 Outsider, 1 Townsfolk is secretly drunk. When the Widow views the Grimoire, they see xX_2662_Xx as the Demon whose ability they have and doesn''t know who is secretly drunk.","id":"widow"},{"name":"Oldephaz","align":"evil","text":"The xX_2662_Xx is considered ''about to die'' if they have the Oldephaz''s ability and more than half of the players have voted to start the Femur Breaker.","slug":"oldephaz"},{"name":"▼","align":"evil","text":"If the Spy or Baron is in-play, instead of adding 1 Outsider, 1 Townsfolk is secretly drunk. When the Spy views the Grimoire, they see xX_2662_Xx as the ∇ and doesn''t know who is secretly drunk. If the xX_2662_Xx dies, their ability lasts (except the killing part) and the Scarlet Woman becomes the ∇","slug":"scp-1936"},{"name":"What Knife?","align":"evil","text":"xX_2662_Xx cannot have the What Knife?''s ability.","slug":"what-knife"},{"name":"Esper","align":"evil","text":"Instead of adding 1 Outsider, 1 Townsfolk is secretly drunk. When the Esper views the Grimoire, they see xX_2662_Xx as the Demon whose ability they have and doesn''t know who is secretly drunk.","id":"esper_the_bootleggers_anthology"},{"name":"Mouldwarp","align":"evil","text":"The Mouldwarp cannot be xX_2662_Xx.","id":"mouldwarp_the_bootleggers_anthology"},{"name":"Kukalpa","align":"evil","text":"xX_2662_Xx''s ability lasts (except their 2nd Demon ability), even if they are dead.","id":"kukalpa_hblreleased"},{"name":"Bloodless","align":"evil","text":"Instead of adding 1 Outsider, 1 Townsfolk is secretly drunk. Once the Bloodless sees the Grimoire, they see xX_2662_Xx as the Demon whose ability they have and doesn''t know who is secretly drunk. If a new Demon is made, the xX_2662_Xx''s ability lasts (except the 2nd Demon ability), and the chosen evil instead becomes that 2nd Demon.","id":"bloodless_darkartists_stuff"}],"firstNight":7.2662,"otherNight":0,"remindersGlobal":["Is xX_2662_Xx"],"setup":true,"special":[{"name":"bag-disabled","type":"selection"},{"name":"replace-character","type":"reveal"}],"firstNightReminder":"Show them the ''You Are'' card, and the xX_2662_Xx character token.","art":"art/xx-2662-xx.png","jsonId":"xx_2662_xx_scp_fragmented_veil","curata":false}','scp-fragmented-veil/xx-2662-xx','published',datetime('now'),datetime('now')),
('bzzip-exe','bzzip.exe','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"bzzip-exe","name":"bzzip.exe","team":"demon","ability":"Each night*, choose a player: they die. The day & night actions run on a timer that gets progressively smaller over time.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-3045 is an executable program that can dynamically \"shortens\" any media inserted into it, until it invariably devolves into swarms of aggressive bees...","summaryBullets":["When bzzip.exe enters play, all players learn that their actions will now be timed, and if they can''t make their input within that time, it is denied.","During the day, the Storyteller imposes the duration of the time limit for how long players have to discuss before & during nominations, and when a player nominates another.","Additionally, the Storyteller may act faster or even prompt players to act faster to continue the speed of the ability.","If a player nominates but doesn''t give their reasoning within the allotted time frame, the Storyteller will cancel the nomination and deny that player from nominating again today.","During the night, the Storyteller imposes the duration of the time limit for how long players have to make their input for their ability {{i|(if it uses one)}}.","If a player wakes but doesn''t give their input for their ability in time, the Storyteller will cancel it and put that player to sleep without acting.","bzzip.exe themselves is not immune to their time-acceleration ability.","The Storyteller will impose shorter time limits each day that passes."],"howToRun":["Each dawn, announce how much time players have to discuss amongst each other before nominations occur, during nominations, and when a player nominates. When a player makes a nomination but doesn''t give their reasoning within the time limit, consider their nomination forfeit and cancel it {{i|(that player cannot make another nomination again today)}}. Each dusk, announce how much time players have to input their actions when woken at night. When a player is woken to input their action but doesn''t give it within the time limit, consider their ability tonight forfeit and cancel it, put them back to sleep.","Each night except the first, wake bzzip.exe. They point at any player. That player {{i|dies}} - mark them with the **DEAD** reminder. Put bzzip.exe to sleep."],"iconBy":"le_nuberto","firstNight":0,"otherNight":39.3045,"reminders":["Dead"],"setup":false,"otherNightReminder":"bzzip.exe points to a player. That player dies.","art":"art/bzzip-exe.png","jsonId":"bzzipexe_scp_fragmented_veil","curata":false}','scp-fragmented-veil/bzzip-exe','published',datetime('now'),datetime('now'));
